package com.mipay.sme.security.rbac;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The portals' menu cells (docs/plans/role-menu-builder.md) ship as rbac/nav-catalogue.json,
 * generated by tools/gen-nav-catalogue.ts. Every id must be a row RBAC accepts
 * (Verbs.parse: ^[a-z]+\.[a-z_]+$), in the nav area, and unique.
 */
class NavCatalogueTest {

    @Test
    void menuCellsLoadAndAreValidRbacRows() {
        EndpointManifestPublisher p = new EndpointManifestPublisher(null, new ObjectMapper());
        List<Map<String, String>> nav = p.navCatalogue();
        assertFalse(nav.isEmpty(), "rbac/nav-catalogue.json is on the classpath");
        Set<String> seen = new HashSet<>();
        for (Map<String, String> n : nav) {
            String id = n.get("id");
            assertTrue(id.matches("^nav\\.[a-z_]+$"), id);
            assertTrue(seen.add(id), "duplicate " + id);
            assertFalse(n.get("description").isBlank(), id);
        }
        assertTrue(seen.contains("nav.supplier_orders_queue"));
        assertTrue(seen.contains("nav.platform_access_users"));
    }
}
